import CryptoKit
import Foundation

/// On-disk cache of `TranslatedPage`s, one small JSON file per page and
/// language pair. Keyed by `ComicPage.id`, which already folds in the source
/// file's size and modification date — replacing a book invalidates its
/// translations the same way it invalidates the image caches.
///
/// Lives under Caches: everything here can be regenerated by translating
/// again, and Settings can clear it.
nonisolated struct TranslationStore: Sendable {
    let root: URL

    init(root: URL = TranslationStore.defaultRoot()) {
        self.root = root
    }

    static func defaultRoot() -> URL {
        let caches = FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask).first
            ?? FileManager.default.temporaryDirectory
        return caches.appendingPathComponent("panely-translation-cache", isDirectory: true)
    }

    /// The scope is part of the key: a slice analyzed on its own and the same
    /// slice read as part of a strip give different (cut vs whole) balloons.
    /// So is the mode, so switching to accurate translates again; accurate
    /// keeps the key it had before modes existed.
    static func key(
        pageID: String,
        from source: TranslationLanguage,
        to target: TranslationLanguage,
        scope: TranslationScope = .page,
        mode: TranslationMode = .accurate
    ) -> String {
        let modeTag = mode == .accurate ? "" : "|\(mode.rawValue)"
        let composite = "\(pageID)|\(source.rawValue)>\(target.rawValue)|\(scope.rawValue)\(modeTag)|v\(TranslatedPage.formatVersion)"
        return SHA256.hash(data: Data(composite.utf8)).prefix(16).map { String(format: "%02x", $0) }.joined()
    }

    func load(key: String) -> TranslatedPage? {
        guard let data = try? Data(contentsOf: fileURL(forKey: key)) else { return nil }
        return try? JSONDecoder().decode(TranslatedPage.self, from: data)
    }

    func save(_ page: TranslatedPage, key: String) throws {
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        try JSONEncoder().encode(page).write(to: fileURL(forKey: key), options: .atomic)
    }

    func sizeBytes() -> UInt64 {
        entries().reduce(UInt64(0)) { total, url in
            let size = (try? url.resourceValues(forKeys: [.fileSizeKey]))?.fileSize ?? 0
            return total + UInt64(max(0, size))
        }
    }

    /// Remove every cached translation; returns the bytes freed.
    @discardableResult
    func clear() -> UInt64 {
        var removed: UInt64 = 0
        for url in entries() {
            let size = (try? url.resourceValues(forKeys: [.fileSizeKey]))?.fileSize ?? 0
            if (try? FileManager.default.removeItem(at: url)) != nil {
                removed += UInt64(max(0, size))
            }
        }
        return removed
    }

    /// Forget these entries (pages to translate again).
    func remove(keys: [String]) {
        for key in keys {
            try? FileManager.default.removeItem(at: fileURL(forKey: key))
        }
    }

    private func fileURL(forKey key: String) -> URL {
        root.appendingPathComponent(key).appendingPathExtension("json")
    }

    private func entries() -> [URL] {
        let urls = (try? FileManager.default.contentsOfDirectory(
            at: root,
            includingPropertiesForKeys: [.fileSizeKey],
            options: [.skipsHiddenFiles]
        )) ?? []
        return urls.filter { $0.pathExtension == "json" }
    }
}
